import hashlib, hmac, secrets
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, EmailStr, Field

app = FastAPI()
USUARIOS = {}          # e-mail -> hash da senha

def criar_hash(senha: str) -> str:
    sal = secrets.token_bytes(16)
    bruto = hashlib.scrypt(senha.encode(), salt=sal, n=16384, r=8, p=1)
    return f"scrypt${sal.hex()}${bruto.hex()}"

def conferir_senha(senha: str, guardado: str) -> bool:
    _, sal_hex, esperado = guardado.split("$")
    bruto = hashlib.scrypt(senha.encode(), salt=bytes.fromhex(sal_hex), n=16384, r=8, p=1)
    return hmac.compare_digest(bruto.hex(), esperado)   # comparação sem vazar tempo

class Credenciais(BaseModel):
    email: EmailStr
    senha: str = Field(min_length=8, max_length=200)

@app.post("/cadastro", status_code=201)
def cadastrar(dados: Credenciais):
    if dados.email in USUARIOS:
        raise HTTPException(status_code=409, detail="e-mail já cadastrado")
    USUARIOS[dados.email] = criar_hash(dados.senha)
    return {"email": dados.email}

@app.post("/login")
def entrar(dados: Credenciais):
    guardado = USUARIOS.get(dados.email)
    if guardado is None or not conferir_senha(dados.senha, guardado):
        raise HTTPException(status_code=401, detail="e-mail ou senha inválidos")
    return {"ok": True}

# o banco guarda scrypt$<sal>$<hash>. A senha, nunca.

