const express = require("express");
const crypto = require("node:crypto");

const app = express();
app.use(express.json());

const USUARIOS = new Map();          // e-mail -> hash da senha

function criarHash(senha) {
  const sal = crypto.randomBytes(16);
  const bruto = crypto.scryptSync(senha, sal, 64);
  return `scrypt$${sal.toString("hex")}$${bruto.toString("hex")}`;
}

function conferirSenha(senha, guardado) {
  const [, salHex, esperado] = guardado.split("$");
  const bruto = crypto.scryptSync(senha, Buffer.from(salHex, "hex"), 64);
  return crypto.timingSafeEqual(bruto, Buffer.from(esperado, "hex"));
}

function credenciais(corpo) {
  const email = corpo?.email;
  const senha = corpo?.senha;
  if (typeof email !== "string" || !email.includes("@") || typeof senha !== "string" || senha.length < 8) {
    return null;
  }
  return { email: email.trim().toLowerCase(), senha };
}

app.post("/cadastro", (req, res) => {
  const dados = credenciais(req.body);
  if (!dados) return res.status(400).json({ erro: "dados inválidos", campos: ["email", "senha"] });
  if (USUARIOS.has(dados.email)) return res.status(409).json({ erro: "e-mail já cadastrado" });

  USUARIOS.set(dados.email, criarHash(dados.senha));
  res.status(201).json({ email: dados.email });
});

app.post("/login", (req, res) => {
  const dados = credenciais(req.body);
  if (!dados) return res.status(400).json({ erro: "dados inválidos", campos: ["email", "senha"] });

  const guardado = USUARIOS.get(dados.email);
  if (!guardado || !conferirSenha(dados.senha, guardado)) {
    return res.status(401).json({ erro: "e-mail ou senha inválidos" });
  }
  res.json({ ok: true });
});

app.listen(3000);

