import base64, hashlib, hmac, json, os, time
from fastapi import FastAPI, HTTPException

app = FastAPI()
SEGREDO = os.environ["APP_SEGREDO"].encode()

def _b64(dados: bytes) -> str:
    return base64.urlsafe_b64encode(dados).decode().rstrip("=")

def _de_b64(texto: str) -> bytes:
    return base64.urlsafe_b64decode(texto + "=" * (-len(texto) % 4))

def criar_token(usuario_id: int, horas: int = 12) -> str:
    corpo = _b64(json.dumps({"sub": usuario_id, "exp": int(time.time()) + horas * 3600}).encode())
    return f"{corpo}.{_b64(hmac.new(SEGREDO, corpo.encode(), hashlib.sha256).digest())}"

def ler_token(token: str):
    try:
        corpo, assinatura = token.split(".")
    except ValueError:
        return None
    esperada = _b64(hmac.new(SEGREDO, corpo.encode(), hashlib.sha256).digest())
    if not hmac.compare_digest(assinatura, esperada):
        return None                      # assinatura não bate: alguém mexeu
    dados = json.loads(_de_b64(corpo))
    return None if dados["exp"] < time.time() else dados["sub"]

@app.post("/login")
def entrar():
    # depois de conferir a senha, como na aula anterior:
    return {"token": criar_token(usuario_id=7)}

