const express = require("express");
const crypto = require("node:crypto");

const app = express();
app.use(express.json());

const SEGREDO = process.env.APP_SEGREDO;
if (!SEGREDO) throw new Error("falta APP_SEGREDO no ambiente");

const assinar = (corpo) => crypto.createHmac("sha256", SEGREDO).update(corpo).digest("base64url");

function criarToken(usuarioId, horas = 12) {
  const dados = { sub: usuarioId, exp: Math.floor(Date.now() / 1000) + horas * 3600 };
  const corpo = Buffer.from(JSON.stringify(dados)).toString("base64url");
  return `${corpo}.${assinar(corpo)}`;
}

function lerToken(token) {
  const [corpo, assinatura] = String(token).split(".");
  if (!corpo || !assinatura) return null;

  const esperada = Buffer.from(assinar(corpo));
  const recebida = Buffer.from(assinatura);
  if (recebida.length !== esperada.length || !crypto.timingSafeEqual(recebida, esperada)) return null;

  const dados = JSON.parse(Buffer.from(corpo, "base64url").toString());
  return dados.exp < Math.floor(Date.now() / 1000) ? null : dados.sub;
}

app.post("/login", (req, res) => {
  // depois de conferir a senha:
  const token = criarToken(7);

  res.cookie("sessao", token, { httpOnly: true, secure: true, sameSite: "lax" });
  res.json({ token });
});

app.listen(3000);

