from fastapi import Depends, FastAPI, Header, HTTPException

app = FastAPI()

TAREFAS = [
    {"id": 1, "usuario_id": 7, "titulo": "Minha tarefa"},
    {"id": 2, "usuario_id": 9, "titulo": "Tarefa de outra pessoa"},
]

def usuario_atual(authorization: str = Header(default="")) -> int:
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="faça login")
    usuario_id = ler_token(authorization.removeprefix("Bearer "))
    if usuario_id is None:
        raise HTTPException(status_code=401, detail="sessão inválida ou vencida")
    return usuario_id

@app.get("/tarefas")
def listar(usuario_id: int = Depends(usuario_atual)):
    return [t for t in TAREFAS if t["usuario_id"] == usuario_id]

@app.get("/tarefas/{id}")
def uma(id: int, usuario_id: int = Depends(usuario_atual)):
    tarefa = next((t for t in TAREFAS if t["id"] == id), None)
    if tarefa is None:
        raise HTTPException(status_code=404, detail="tarefa não encontrada")
    if tarefa["usuario_id"] != usuario_id:
        raise HTTPException(status_code=403, detail="sem permissão")
    return tarefa

@app.post("/tarefas", status_code=201)
