from functools import wraps
from flask import Flask, g, request

app = Flask(__name__)

TAREFAS = [
    {"id": 1, "usuario_id": 7, "titulo": "Minha tarefa"},
    {"id": 2, "usuario_id": 9, "titulo": "Tarefa de outra pessoa"},
]

def exige_login(rota):
    @wraps(rota)
    def dentro(*args, **kwargs):
        cabecalho = request.headers.get("Authorization", "")
        if not cabecalho.startswith("Bearer "):
            return {"erro": "faça login"}, 401
        usuario_id = ler_token(cabecalho.removeprefix("Bearer "))
        if usuario_id is None:
            return {"erro": "sessão inválida ou vencida"}, 401
        g.usuario_id = usuario_id
        return rota(*args, **kwargs)
    return dentro

@app.get("/tarefas")
@exige_login
def listar():
    return [t for t in TAREFAS if t["usuario_id"] == g.usuario_id]

@app.get("/tarefas/<int:id>")
@exige_login
def uma(id):
    tarefa = next((t for t in TAREFAS if t["id"] == id), None)
    if tarefa is None:
        return {"erro": "tarefa não encontrada"}, 404
    if tarefa["usuario_id"] != g.usuario_id:
        return {"erro": "sem permissão"}, 403
    return tarefa

# os quatro testes dão 401, 401, 200 (só as minhas) e 403.
# o @wraps não é enfeite: sem ele, todas as rotas decoradas passam a se
# chamar "dentro" e o Flask recusa a segunda com erro de nome repetido.

