const express = require("express");

const app = express();
app.use(express.json());

const TAREFAS = [
  { id: 1, usuario_id: 7, titulo: "Minha tarefa" },
  { id: 2, usuario_id: 9, titulo: "Tarefa de outra pessoa" },
];

function exigeLogin(req, res, proximo) {
  const cabecalho = req.headers.authorization ?? "";
  if (!cabecalho.startsWith("Bearer ")) return res.status(401).json({ erro: "faça login" });

  const usuarioId = lerToken(cabecalho.slice("Bearer ".length));
  if (usuarioId === null) return res.status(401).json({ erro: "sessão inválida ou vencida" });

  req.usuarioId = usuarioId;
  proximo();
}

// aplicado no grupo inteiro: rota nova já nasce protegida
app.use("/tarefas", exigeLogin);

app.get("/tarefas", (req, res) => {
  res.json(TAREFAS.filter((t) => t.usuario_id === req.usuarioId));
});

app.get("/tarefas/:id", (req, res) => {
  const tarefa = TAREFAS.find((t) => t.id === Number(req.params.id));
  if (!tarefa) return res.status(404).json({ erro: "tarefa não encontrada" });
  if (tarefa.usuario_id !== req.usuarioId) return res.status(403).json({ erro: "sem permissão" });
  res.json(tarefa);
});

app.post("/tarefas", (req, res) => {
  const tarefa = { id: TAREFAS.length + 1, usuario_id: req.usuarioId, titulo: req.body.titulo };
  TAREFAS.push(tarefa);            // o dono vem do token
  res.status(201).json(tarefa);
});

app.listen(3000);

// os quatro testes dão 401, 401, 200 (só as minhas) e 403.
// proteger o grupo com app.use é melhor que lembrar em cada rota:
// o que se esquece uma vez, se esquece sempre.

